// Les deux paramètres sont facultatifs : sans rien, on renvoie les 54.
// La validation de `book` appartient à l'API, qui répond 400 avec la liste des
// livres valides — la dupliquer ici créerait deux sources de vérité.
const input = $input.first().json;
const query = input.query || {};

const book = (query.book || '').trim();
const language = (query.language || '').trim();

const params = [];
if (book) params.push('book=' + encodeURIComponent(book));
if (language) params.push('language=' + encodeURIComponent(language));

return [{
  json: {
    book: book || null,
    language: language || null,
    requete: params.length ? '?' + params.join('&') : ''
  }
}];

// L'API répond {success, count, parashiyot[]}. On relaie tel quel en surface,
// et on rend l'erreur exploitable : sur un livre inconnu elle renvoie 400 avec
// la liste des cinq livres valides dans `detail` — cette liste est ce qui permet
// à l'appelant de corriger, elle doit donc remonter jusqu'à lui.
const input = $input.first().json;
const data = input.body || input;
const code = input.statusCode || 200;
const params = $('Lire Paramètres').first().json;

if (code >= 400) {
  return [{
    json: {
      success: false,
      error: {
        code: code,
        message: data?.detail || data?.error?.message || 'Requête refusée par l\'API',
        status: code === 400 ? 'INVALID_BOOK' : 'API_ERROR'
      },
      book: params.book,
      language: params.language
    }
  }];
}

const liste = data.parashiyot || [];

return [{
  json: {
    success: true,
    count: data.count ?? liste.length,
    book: params.book,
    language: params.language,
    parashiyot: liste
  }
}];
